//! Checks that `src/kernel/exports.in`, the method list of the kernel traits, matches the ordinal
//! tables of `ferrum-xex`.
//!
//! The file is generated by this test: after the tables change, run
//!
//! ```text
//! FERRUM_BLESS=1 cargo test -p ferrum-runtime --test kernel_exports
//! ```
//!
//! and commit the result.

use std::collections::HashSet;
use std::fmt::Write as _;
use std::path::Path;

use ferrum_xex::ordinals::{ImportKind, KnownLibrary, OrdinalEntry, TABLES_LICENSE};

/// Where the generated file lives.
const EXPORTS: &str = concat!(env!("CARGO_MANIFEST_DIR"), "/src/kernel/exports.in");

/// Methods every kernel trait has besides the exports, which no export may be named.
const FIXED_METHODS: [&str; 2] = ["resolve_variable", "unnamed_import"];

/// Every keyword of Rust 2021, strict, reserved and weak, and those of later editions.
const KEYWORDS: &[&str] = &[
    "as",
    "async",
    "await",
    "break",
    "const",
    "continue",
    "crate",
    "dyn",
    "else",
    "enum",
    "extern",
    "false",
    "fn",
    "for",
    "if",
    "impl",
    "in",
    "let",
    "loop",
    "match",
    "mod",
    "move",
    "mut",
    "pub",
    "ref",
    "return",
    "self",
    "Self",
    "static",
    "struct",
    "super",
    "trait",
    "true",
    "type",
    "unsafe",
    "use",
    "where",
    "while",
    "abstract",
    "become",
    "box",
    "do",
    "final",
    "macro",
    "override",
    "priv",
    "typeof",
    "unsized",
    "virtual",
    "yield",
    "try",
    "gen",
    "union",
    "raw",
    "safe",
    "macro_rules",
];

/// The libraries with a kernel trait: the trait's name, the library's file name and the first
/// line of the trait's documentation.
const LIBRARIES: [(KnownLibrary, &str, &str, &str); 2] = [
    (
        KnownLibrary::Xboxkrnl,
        "Xboxkrnl",
        "xboxkrnl.exe",
        "The functions of `xboxkrnl.exe`, the kernel.",
    ),
    (
        KnownLibrary::Xam,
        "Xam",
        "xam.xex",
        "The functions of `xam.xex`, the system application layer.",
    ),
];

/// Returns the function exports of `library`, which become methods.
fn functions(library: KnownLibrary) -> impl Iterator<Item = &'static OrdinalEntry> {
    library
        .table()
        .iter()
        .filter(|entry| entry.kind == ImportKind::Function)
}

/// Returns the text `src/kernel/exports.in` has to hold.
fn render() -> String {
    let mut out = String::from(
        "// @generated by crates/ferrum-runtime/tests/kernel_exports.rs from the ordinal tables of\n\
         // Xenia, which ferrum-xex keeps verbatim under crates/ferrum-xex/tables/xenia/. Do not edit\n\
         // this file; regenerate it with\n\
         //\n\
         //     FERRUM_BLESS=1 cargo test -p ferrum-runtime --test kernel_exports\n\
         //\n\
         // The names and ordinals below come from those tables and are under their license:\n\
         //\n",
    );
    for line in TABLES_LICENSE.lines() {
        if line.is_empty() {
            out.push_str("//\n");
        } else {
            writeln!(out, "// {line}").unwrap();
        }
    }
    for (library, name, file, doc) in LIBRARIES {
        writeln!(
            out,
            "\nkernel_trait! {{\n    /// {doc}\n    {name}, \"{file}\" {{"
        )
        .unwrap();
        for entry in functions(library) {
            writeln!(out, "        0x{:04X} {},", entry.ordinal, entry.name).unwrap();
        }
        out.push_str("    }\n}\n");
    }
    out
}

#[test]
fn exports_in_matches_the_ordinal_tables() {
    let expected = render();
    if std::env::var_os("FERRUM_BLESS").is_some() {
        std::fs::write(EXPORTS, &expected).expect("write src/kernel/exports.in");
    }
    let actual = std::fs::read_to_string(Path::new(EXPORTS))
        .expect("read src/kernel/exports.in")
        .replace("\r\n", "\n");
    assert!(
        actual == expected,
        "src/kernel/exports.in is out of date; regenerate it with \
         FERRUM_BLESS=1 cargo test -p ferrum-runtime --test kernel_exports"
    );
}

#[test]
fn every_function_export_can_be_a_method() {
    for (library, ..) in LIBRARIES {
        let mut seen = HashSet::new();
        for entry in functions(library) {
            let name = entry.name;
            let mut chars = name.chars();
            let first = chars.next().expect("a name");
            assert!(
                (first.is_ascii_alphabetic() || first == '_')
                    && chars.all(|c| c.is_ascii_alphanumeric() || c == '_')
                    && name != "_",
                "{library:?}: {name} is not an identifier"
            );
            assert!(
                !KEYWORDS.contains(&name),
                "{library:?}: {name} is a keyword"
            );
            assert!(
                !FIXED_METHODS.contains(&name),
                "{library:?}: {name} clashes with a method of every kernel trait"
            );
            assert!(seen.insert(name), "{library:?}: {name} repeats");
        }
    }
}

#[test]
fn the_traits_cover_every_function_and_no_variable() {
    let count = |library| functions(library).count();
    assert_eq!(count(KnownLibrary::Xboxkrnl), 887);
    assert_eq!(count(KnownLibrary::Xam), 1733);
    let rendered = render();
    for (library, ..) in LIBRARIES {
        for entry in library.table() {
            let line = format!("        0x{:04X} {},\n", entry.ordinal, entry.name);
            let present = rendered.contains(&line);
            assert_eq!(
                present,
                entry.kind == ImportKind::Function,
                "{library:?}: {}",
                entry.name
            );
        }
    }
}
